solution:
import { useState, useCallback } from 'react';

type StateConfig = {
  on: Record<string, (ctx: any) => string | null>;
};

type FSMConfig = {
  initial: string;
  states: Record<string, StateConfig>;
};

export function useFSM(config: FSMConfig) {
  const [state, setState] = useState(config.initial);

  const send = useCallback((event: string) => {
    setState(current => {
      const handler = config.states[current]?.on[event];
      if (!handler) return current;
      const next = handler(null);
      return next ?? current;
    });
  }, [config]);

  const can = useCallback((event: string) => {
    return event in (config.states[state]?.on ?? {});
  }, [config, state]);

  const matches = useCallback((s: string) => state === s, [state]);

  return { state, send, can, matches };
}
